_DURATION_RE = re.compile(
    r"\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*"
)

_MULTIPLIERS = (24 * 60 * 60, 60 * 60, 60, 1)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _DURATION_RE.fullmatch(s)
    if match is None:
        raise ValueError("invalid duration")

    amounts = match.groups()
    if all(amount is None for amount in amounts):
        raise ValueError("duration must contain at least one unit")

    return sum(
        int(amount) * multiplier
        for amount, multiplier in zip(amounts, _MULTIPLIERS)
        if amount is not None
    )
